package com.example.myfirstapplication;import android.app.AlertDialog;import android.os.Bundle;import android.os.RemoteException;import android.util.Log;import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.ImageButton;import android.widget.LinearLayout;import android.widget.NumberPicker;import androidx.annotation.NonNull;import androidx.appcompat.widget.PopupMenu;import androidx.appcompat.widget.SearchView;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.LinearLayoutManager;import androidx.recyclerview.widget.RecyclerView;import com.example.myapplication2.IPaymentService;import com.example.myapplication2.TransactionData;import java.text.SimpleDateFormat;import java.util.ArrayList;import java.util.Calendar;import java.util.Date;import java.util.List;import java.util.Locale;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;public class TransactionHistoryFragment extends Fragment {    private static final String TAG = "TransactionHistory";    private RecyclerView transactionView;    private TransactionAdapter adapter;    private SearchView searchView;    private final List<TransactionData> allTransactions =            new ArrayList<>();    private final ExecutorService executorService =            Executors.newSingleThreadExecutor();    @Override    public View onCreateView(            LayoutInflater inflater,            ViewGroup container,            Bundle savedInstanceState) {        return inflater.inflate(                R.layout.fragment_transaction_history,                container,                false        );    }    @Override    public void onViewCreated(            @NonNull View view,            Bundle savedInstanceState) {        super.onViewCreated(view, savedInstanceState);        transactionView =                view.findViewById(                        R.id.transactionView                );        searchView =                view.findViewById(                        R.id.searchViewTransactionHistory                );        transactionView.setLayoutManager(                new LinearLayoutManager(requireContext())        );        adapter = new TransactionAdapter(                requireContext(),                allTransactions        );        transactionView.setAdapter(adapter);        setupSearch();        setupDateFilter();        /*         * Load transactions from App2.         */        loadTransactions();    }    private void loadTransactions() {        if (!(requireActivity()                instanceof MainActivity)) {            Log.e(TAG,                    "Activity is not MainActivity");            return;        }        MainActivity activity =                (MainActivity) requireActivity();        IPaymentService service =                activity.getPaymentService();        if (service == null) {            Log.e(TAG,                    "Payment service is not connected");            return;        }        executorService.execute(() -> {            try {                List<TransactionData> transactions =                        service.getTransactions();                requireActivity().runOnUiThread(() -> {                    allTransactions.clear();                    if (transactions != null) {                        allTransactions.addAll(                                transactions                        );                    }                    adapter.setTransactionList(                            allTransactions                    );                    Log.d(                            TAG,                            "Transactions received: "                                    + allTransactions.size()                    );                });            } catch (RemoteException e) {                Log.e(                        TAG,                        "Failed to get transactions",                        e                );                requireActivity().runOnUiThread(() ->                        adapter.setTransactionList(                                new ArrayList<>()                        )                );            }        });    }    private void setupSearch() {        searchView.setOnQueryTextListener(                new SearchView.OnQueryTextListener() {                    @Override                    public boolean onQueryTextSubmit(                            String query) {                        filterTransactions(query);                        return true;                    }                    @Override                    public boolean onQueryTextChange(                            String newText) {                        filterTransactions(newText);                        return true;                    }                }        );    }    private void filterTransactions(            String query) {        String search =                query == null                        ? ""                        : query.trim().toLowerCase(                        Locale.getDefault()                );        if (search.isEmpty()) {            adapter.setTransactionList(                    allTransactions            );            return;        }        List<TransactionData> filtered =                new ArrayList<>();        for (TransactionData transaction :                allTransactions) {            boolean matchesAmount =                    transaction.getAmount() != null &&                            transaction.getAmount()                                    .toLowerCase()                                    .contains(search);            boolean matchesCard =                    transaction.getCardNo() != null &&                            transaction.getCardNo()                                    .toLowerCase()                                    .contains(search);            boolean matchesName =                    transaction.getCardHolderName() != null &&                            transaction.getCardHolderName()                                    .toLowerCase()                                    .contains(search);            boolean matchesRemarks =                    transaction.getRemarks() != null &&                            transaction.getRemarks()                                    .toLowerCase()                                    .contains(search);            if (matchesAmount ||                    matchesCard ||                    matchesName ||                    matchesRemarks) {                filtered.add(transaction);            }        }        adapter.setTransactionList(filtered);    }    private void setupDateFilter() {        ImageButton imgbtn =                viewButton();        if (imgbtn == null) {            return;        }        imgbtn.setOnClickListener(v -> {            PopupMenu popupMenu =                    new PopupMenu(                            requireContext(),                            imgbtn                    );            popupMenu.getMenu().add("Today");            popupMenu.getMenu().add("Last Week");            popupMenu.getMenu().add("Last Month");            popupMenu.getMenu().add("Custom");            popupMenu.setOnMenuItemClickListener(                    item -> {                        String selected =                                item.getTitle().toString();                        switch (selected) {                            case "Today":                                filterToday();                                break;                            case "Last Week":                                filterLastWeek();                                break;                            case "Last Month":                                filterLastMonth();                                break;                            case "Custom":                                openCustomMonthPicker();                                break;                        }                        return true;                    }            );            popupMenu.show();        });    }    private ImageButton viewButton() {        if (getView() == null) {            return null;        }        return getView().findViewById(                R.id.btnDateFilter        );    }    private void filterToday() {        String today =                new SimpleDateFormat(                        "yyyy-MM-dd",                        Locale.getDefault()                ).format(new Date());        filterByDateRange(                today + " 00:00:00",                today + " 23:59:59"        );    }    private void filterLastWeek() {        Calendar calendar =                Calendar.getInstance();        String endDate =                formatDateTime(                        calendar.getTime()                );        calendar.add(                Calendar.DAY_OF_YEAR,                -7        );        String startDate =                formatDateTime(                        calendar.getTime()                );        filterByDateRange(                startDate,                endDate        );    }    private void filterLastMonth() {        Calendar calendar =                Calendar.getInstance();        String endDate =                formatDateTime(                        calendar.getTime()                );        calendar.add(                Calendar.MONTH,                -1        );        String startDate =                formatDateTime(                        calendar.getTime()                );        filterByDateRange(                startDate,                endDate        );    }    private String formatDateTime(Date date) {        return new SimpleDateFormat(                "yyyy-MM-dd HH:mm:ss",                Locale.getDefault()        ).format(date);    }    private void filterByDateRange(            String startDate,            String endDate) {        List<TransactionData> filtered =                new ArrayList<>();        for (TransactionData transaction :                allTransactions) {            String transactionDate =                    transaction.getDatetime();            if (transactionDate == null) {                continue;            }            if (transactionDate.compareTo(startDate) >= 0 &&                    transactionDate.compareTo(endDate) <= 0) {                filtered.add(transaction);            }        }        adapter.setTransactionList(filtered);    }    private void openCustomMonthPicker() {        String[] months = {                "January",                "February",                "March",                "April",                "May",                "June",                "July",                "August",                "September",                "October",                "November",                "December"        };        View dialogView =                LayoutInflater.from(requireContext())                        .inflate(                                R.layout.dialog_month_spinner,                                null                        );        NumberPicker monthPicker =                dialogView.findViewById(                        R.id.monthSpinner                );        monthPicker.setMinValue(0);        monthPicker.setMaxValue(11);        monthPicker.setDisplayedValues(months);        Calendar calendar =                Calendar.getInstance();        monthPicker.setValue(                calendar.get(Calendar.MONTH)        );        new AlertDialog.Builder(requireContext())                .setTitle("Select Month")                .setView(dialogView)                .setPositiveButton(                        "OK",                        (dialog, which) -> {                            filterByMonth(                                    monthPicker.getValue()                            );                        }                )                .setNegativeButton(                        "Cancel",                        null                )                .show();    }    private void filterByMonth(int month) {        Calendar calendar =                Calendar.getInstance();        int year =                calendar.get(Calendar.YEAR);        Calendar start =                Calendar.getInstance();        start.set(                year,                month,                1,                0,                0,                0        );        start.set(                Calendar.MILLISECOND,                0        );        Calendar end =                Calendar.getInstance();        end.set(                year,                month,                1,                23,                59,                59        );        end.set(                Calendar.DAY_OF_MONTH,                end.getActualMaximum(                        Calendar.DAY_OF_MONTH                )        );        filterByDateRange(                formatDateTime(start.getTime()),                formatDateTime(end.getTime())        );    }    @Override    public void onDestroyView() {        super.onDestroyView();        /*         * Do not shut down the AIDL service here.         *         * The service connection belongs to MainActivity.         */    }}